namespace speed {
namespace {
const CanisBlazeDefinition &rule(const ContentBundle &c,uint32_t definition) {return *std::find_if(c.canis_blazes.begin(),c.canis_blazes.end(),[&](const auto &v){return v.technique==definition;});}
bool live(const RunRuntime &r,EnemyHandle h) {return r.state.enemy_handles.contains(h) && !r.state.enemies[h.slot].dead;}
void resize(godot::RunState::Enemy &e,double hp) {e.hp=hp*e.hp/std::max(0.001,e.max_hp);e.max_hp=hp;}
void ignite(RunRuntime &r,BossBodyState &b,const TechniqueState &t,EnemyHandle actor) {
    auto &e=r.state.enemies[actor.slot];const auto old=std::find_if(b.canis.led.begin(),b.canis.led.end(),[&](const auto &v){return same_handle(v.actor,actor);});CanisBurningHound v;v.actor=actor;v.definition=rule(*r.content,t.definition).id;v.technique=t.definition;v.base_hp=old==b.canis.led.end()?e.max_hp:old->base_hp;v.color=old==b.canis.led.end()?r.content->definitions[e.definition].color:old->color;if (old!=b.canis.led.end()) b.canis.led.erase(old);b.canis.burning.push_back(v);const auto &c=r.state.combat_config;resize(e,c.base_attack*c.attack_mult*c.atk_scale*std::max(1.0,r.state.loadout.full_charge_maximum)*0.5);GroupSystem::release_order(r.state,actor);CanisTechnique::cue(r,t,"blaze_ignite",actor);
}
void cue(RunRuntime &r,const BossBodyState &b,const CanisBurningHound &v,const char *name,double radius=-1,double initial_age=0) {TechniqueState t;t.actor=b.actor;t.definition=v.technique;CanisTechnique::cue(r,t,name,v.actor,radius,v.definition,initial_age);}
}
bool CanisBlaze::ready(const RunRuntime &r,EnemyHandle actor,uint32_t definition) {const auto *b=PhaseController::find(r,actor);const auto p=std::find_if(r.content->canis_blazes.begin(),r.content->canis_blazes.end(),[&](const auto &p){return p.technique==definition;});return b && !b->canis.barking && !b->canis.calling && live(r,actor) && p!=r.content->canis_blazes.end() && b->canis.led.size()>=p->min_hounds;}
double CanisBlaze::attack_length(const RunRuntime &r,uint32_t definition) {const auto &p=rule(*r.content,definition);return std::max(r.content->boss_techniques[definition-1].warn,p.ignite_at+std::max(int64_t(0),int64_t(p.count)-1)*p.ignite_step)+0.1;}
void CanisBlaze::begin(RunRuntime &r,TechniqueState &t) {t.detail=CanisBlazeState{};auto &v=std::get<CanisBlazeState>(t.detail);const auto *b=PhaseController::find(r,t.actor);const auto &p=rule(*r.content,t.definition);r.state.enemies[t.actor.slot].vel={};std::vector<EnemyHandle> rows;for (const auto &m:b->canis.led) if (live(r,m.actor) && !CanisHowl::in_ring(*b,m.actor) && std::none_of(b->canis.lunging.begin(),b->canis.lunging.end(),[&](auto h){return same_handle(h,m.actor);})) rows.push_back(m.actor);std::stable_sort(rows.begin(),rows.end(),[&](auto a,auto b){return r.state.enemies[a.slot].pos.distance_squared_to(r.state.ship_pos)<r.state.enemies[b.slot].pos.distance_squared_to(r.state.ship_pos);});if (rows.size()>p.count) rows.resize(p.count);for (size_t k=0;k<rows.size();++k) v.chosen.push_back({rows[k],p.ignite_at+k*p.ignite_step,false,false});CanisTechnique::cue(r,t,"blaze_windup");}
void CanisBlaze::step(RunRuntime &r,TechniqueState &t,double dt) {auto &v=std::get<CanisBlazeState>(t.detail);const auto &base=r.content->boss_techniques[t.definition-1];const auto &p=rule(*r.content,t.definition);r.state.enemies[t.actor.slot].vel={};if (t.stage==TechniqueStage::Recovery) {t.remaining=std::max(0.0,t.remaining-dt);if (t.remaining<=0) t.stage=TechniqueStage::Finished;return;}auto *b=PhaseController::find(r,t.actor);if (!b) {t.stage=TechniqueStage::Failed;return;}v.age+=dt;if (v.age<base.warn && base.track_during_warn) CanisTechnique::face(r,t,r.state.enemy_aim,r.content->bosses[base.boss-1].turn,dt);for (auto &item:v.chosen) {if (!live(r,item.actor)) continue;if (!item.sent && v.age>=item.at-p.ignite_step) {item.sent=true;CanisFlames::begin(r,*b,p.flame,item.actor,0,t.definition);}if (!item.lit && v.age>=item.at) {item.lit=true;ignite(r,*b,t,item.actor);}}if (v.age>=std::max(base.warn,p.ignite_at+std::max(int64_t(0),int64_t(v.chosen.size())-1)*p.ignite_step)) {t.stage=TechniqueStage::Recovery;t.remaining=base.recover;t.locked=false;CanisTechnique::cue(r,t,"recovery_started");}}
bool CanisBlaze::validate(const TechniqueState &t) {const auto *v=std::get_if<CanisBlazeState>(&t.detail);if (!v || !std::isfinite(v->age) || v->age<0) return false;std::unordered_set<uint64_t> seen;for (const auto &item:v->chosen) if (!seen.insert(handle_key(item.actor)).second || !std::isfinite(item.at) || item.at<0 || (item.lit && !item.sent)) return false;return true;}
double CanisBlaze::progress(const TechniqueState &t,const BossTechniqueDefinition &p) {return t.stage==TechniqueStage::Windup?std::clamp(std::get<CanisBlazeState>(t.detail).age/std::max(p.warn,0.001),0.0,1.0):0;}
godot::Dictionary CanisBlaze::snapshot(const RunRuntime &r,const TechniqueState &t) {const auto &v=std::get<CanisBlazeState>(t.detail);godot::Dictionary out;out["age"]=v.age;out["flame_profile"]=rule(*r.content,t.definition).flame;out["windup_progress"]=progress(t,r.content->boss_techniques[t.definition-1]);godot::Array chosen;for (const auto &item:v.chosen) {godot::Dictionary q;q["actor"]=r.state.enemy_handles.entity_id(item.actor);q["at"]=item.at;q["sent"]=item.sent;q["lit"]=item.lit;chosen.push_back(q);}out["chosen"]=chosen;return out;}
bool CanisBlaze::burning(const BossBodyState &b,EnemyHandle actor) {return std::any_of(b.canis.burning.begin(),b.canis.burning.end(),[&](const auto &v){return same_handle(v.actor,actor);});}
void CanisBlaze::burning_tick(RunRuntime &r,BossBodyState &b,double dt) {
    for (auto it=b.canis.burning.begin();it!=b.canis.burning.end();) {
        auto &v=*it;if (!live(r,v.actor)) {it=b.canis.burning.erase(it);continue;}const auto &p=r.content->canis_blazes[v.definition-1];const auto &base=r.content->boss_techniques[v.technique-1];auto &e=r.state.enemies[v.actor.slot];v.age+=dt;bool blinking=v.blink_age>=0;if (!blinking && (e.pos.distance_to(r.state.ship_pos)<p.stop_dist || v.age>=p.max_run)) {v.blink_age=0;blinking=true;cue(r,b,v,"blaze_blink");}const HoundSteering config{p.arrive,p.decel,p.face_turn,p.turn_slow,p.turn_fast,p.turn_switch,p.run_speed,p.accel};GroupSystem::steer(r.state,v.actor,blinking?e.pos:r.state.ship_pos,r.state.ship_pos,r.state.world_time+0.3,config);if (!blinking) {++it;continue;}v.blink_age+=dt;const double progress=std::clamp(v.blink_age/std::max(p.blink,0.001),0.0,1.0);e.flash=std::sin(progress*(3+progress*5)*godot::Math::TAU)>0?0.05:0;if (v.blink_age>=p.blink) {cue(r,b,v,"blaze_explode",p.explode_radius,dt);if (e.pos.distance_to(r.state.ship_pos)<=p.explode_radius+r.state.ship_config.ship_radius) {ShipDamageRequest request;request.amount=base.damage;request.scale=DamageScale::AtkScale;request.cause=Cause::Blaze;request.source=r.state.enemies[b.actor.slot].definition+1;request.technique=v.technique;request.hit_policy=HitPolicy::MarkBefore;CombatResolver::ship_damage(r,request);}EnemySystem::mark_dead(r,v.actor);it=b.canis.burning.erase(it);}else ++it;
    }
}
void CanisBlaze::clear(RunRuntime &r,BossBodyState &b) {for (const auto &v:b.canis.burning) if (live(r,v.actor)) {GroupSystem::release_order(r.state,v.actor);resize(r.state.enemies[v.actor.slot],v.base_hp);}b.canis.burning.clear();}
bool CanisBlaze::validate_body(const godot::RunState &s,const ContentBundle &c,const BossBodyState &b) {std::unordered_set<uint64_t> seen;for (const auto &v:b.canis.burning) {if (!seen.insert(handle_key(v.actor)).second || !v.definition || v.definition>c.canis_blazes.size() || !v.technique || v.technique>c.boss_techniques.size() || c.canis_blazes[v.definition-1].technique!=v.technique || v.base_hp<=0 || v.age<0 || v.blink_age< -1) return false;for (double x:{v.base_hp,v.age,v.blink_age}) if (!std::isfinite(x)) return false;if (s.enemy_handles.contains(v.actor) && c.definitions[s.enemies[v.actor.slot].definition].kind!=EnemyDefinition::Kind::Hound) return false;}return true;}
void CanisBlaze::body_snapshot(const RunRuntime &r,const BossBodyState &b,godot::Dictionary &out) {godot::Array burning;for (const auto &v:b.canis.burning) if (live(r,v.actor)) {const auto &e=r.state.enemies[v.actor.slot];godot::Dictionary q;q["actor"]=r.state.enemy_handles.entity_id(v.actor);q["profile"]=v.definition;q["technique"]=v.technique;q["position"]=e.pos;q["radius"]=e.radius;q["flash"]=e.flash;q["max_hp"]=e.max_hp;q["base_hp"]=v.base_hp;q["age"]=v.age;q["blink_age"]=v.blink_age;burning.push_back(q);}out["burning"]=burning;}
}
